// Classificação determinística; não é uma classificação por IA.
const b = $json.body || $json;
function text(value, max, label) {
  if (typeof value !== 'string' || !value.trim() || value.trim().length > max) throw new Error('Entrada inválida: ' + label);
  return value.trim();
}
const event_id = text(b.event_id || b.message_id, 160, 'event_id estável obrigatório');
const name = text(b.name, 240, 'name');
const summary = text(b.summary || b.message || b.text, 10000, 'summary/message/text').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const source = b.source || 'form';
if (!['email', 'form'].includes(source)) throw new Error('Fonte inválida: use email ou form');
const detectedEmail = summary.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0] || '';
const email = b.email || detectedEmail;
if (typeof email !== 'string' || email.length > 255 || (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))) throw new Error('Email inválido');
const detectedPhone = summary.match(/(?:whatsapp|telefone|celular|tel)\s*[:=-]?\s*(\+?\d[\d\s().-]{7,24}\d)/i)?.[1] || '';
const rawPhone = b.phone || detectedPhone;
if (typeof rawPhone !== 'string' || rawPhone.length > 100) throw new Error('Telefone inválido');
const phone = rawPhone.replace(/\D/g, '');
if (phone && (phone.length < 8 || phone.length > 15)) throw new Error('Telefone inválido');
const normalized = summary.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const rules = [['landing', 'Landing page'], ['site institucional', 'Site institucional'], ['site', 'Site'], ['crm', 'CRM'], ['automacao', 'Automação'], ['whatsapp', 'WhatsApp']];
const classification = 'Regra local: ' + (rules.find(([word]) => normalized.includes(word))?.[1] || 'Revisar');
const evidence_reference = text(b.evidence_reference || source + '/' + event_id, 500, 'evidence_reference');
return {json: {event_id, source, name, summary, phone, email: email.toLowerCase(), classification, evidence_reference}};

const b = $json.body || $json;
const niches = ['dentists', 'clinics', 'restaurants', 'beauty', 'gyms', 'shops'];
if (!niches.includes(b.niche)) throw new Error('Nicho inválido');
if (typeof b.city !== 'string' || !b.city.trim() || b.city.length > 100 || /[";\\\n\r\[\]{}()]/.test(b.city)) throw new Error('Cidade inválida');
const limit = b.limit === undefined ? 10 : Number(b.limit);
if (!Number.isInteger(limit) || limit < 1 || limit > 50) throw new Error('Limite deve ser inteiro entre 1 e 50');
return {json: {niche: b.niche, city: b.city.trim(), limit}};

if (!Array.isArray($json.items) || $json.items.length > 50) throw new Error('Resposta OpenStreetMap inválida');
return $json.items.map((lead, index) => {
  if (lead.source !== 'OpenStreetMap' || !/^(node|way|relation)\/\d+$/.test(lead.source_key || '') || typeof lead.name !== 'string' || !lead.name.trim() || typeof lead.niche !== 'string' || typeof lead.queried_at !== 'string') throw new Error('Referência OpenStreetMap inválida');
  return {json: {source_key: lead.source_key, name: lead.name, niche: lead.niche, address: lead.address || '', phone: lead.phone || '', website: lead.website || null, queried_at: lead.queried_at}, pairedItem: {item: 0}};
});

// CONFIGURAR no nó antes do teste. Nenhuma URL recebida escolhe o host da API.
const PROVIDER_URL = 'https://configure-authorized-price-api.invalid/quote';
const PRODUCT_HOSTS = [];
function host(value) {
  if (typeof value !== 'string' || /[\\\s]/.test(value)) throw new Error('URL HTTPS inválida');
  const match = value.match(/^https:\/\/([a-z0-9.-]+)(?:\/[^#]*)?$/i);
  if (!match) throw new Error('URL HTTPS inválida');
  return match[1].toLowerCase();
}
if (host(PROVIDER_URL).endsWith('.invalid') || !PRODUCT_HOSTS.length) throw new Error('CONFIGURAR API autorizada e PRODUCT_HOSTS antes de executar');
return $input.all().flatMap((item, index) => {
  const watch = item.json;
  if (typeof watch.id !== 'string' || !/^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(watch.id)) throw new Error('Monitor inválido');
  // Desejos sem link continuam aguardando configuração; não inventar consulta.
  if (watch.product_url === null || watch.product_url === '') return [];
  if (!PRODUCT_HOSTS.includes(host(watch.product_url))) throw new Error('Produto fora da allowlist autorizada');
  return [{json: {watch_id: watch.id, product_url: watch.product_url, provider_url: PROVIDER_URL}, pairedItem: {item: index}}];
});

if (!Number.isInteger($json.statusCode) || $json.statusCode < 200 || $json.statusCode >= 300 || !$json.body || typeof $json.body !== 'object' || Array.isArray($json.body)) throw new Error('API não retornou um objeto de cotação válido');
const quote = $json.body;
const monitor = $('PREÇOS · Preparar consultas autorizadas').item.json;
if (quote.currency !== 'BRL' || typeof quote.price !== 'number' || !Number.isFinite(quote.price) || quote.price <= 0 || quote.price > 999999999.99 || Math.abs(quote.price * 100 - Math.round(quote.price * 100)) > 0.00001) throw new Error('Cotação deve conter preço real em BRL com duas casas decimais');
if (quote.product_url !== monitor.product_url) throw new Error('Cotação de outro produto/variação');
if (typeof quote.event_id !== 'string' || !quote.event_id.trim() || quote.event_id.length > 160 || typeof quote.store !== 'string' || !quote.store.trim() || quote.store.length > 240) throw new Error('Cotação sem identificador estável ou loja');
const observed = Date.parse(quote.observed_at);
if (typeof quote.observed_at !== 'string' || !Number.isFinite(observed) || observed > Date.now() + 60000 || observed < Date.now() - 7 * 86400000) throw new Error('Data real da cotação ausente ou inválida');
return {json: {watch_id: monitor.watch_id, event_id: quote.event_id.trim(), store: quote.store.trim(), product_url: quote.product_url, price: quote.price, observed_at: quote.observed_at}};

const b = $json.body || $json;
if (typeof b.project_id !== 'string' || !/^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(b.project_id)) throw new Error('project_id deve ser UUID');
if (!b.report || typeof b.report !== 'object' || Array.isArray(b.report) || b.report.schema_version !== 1) throw new Error('Relatório v1 obrigatório');
// O backend verifica SHA, evidências do repositório e critérios; nunca conclui o marco.
return {json: {project_id: b.project_id.toLowerCase(), report: b.report}};

const headers = $json.headers || {};
const signature = headers['x-hub-signature-256'];
const event = headers['x-github-event'];
const delivery = headers['x-github-delivery'];
if (typeof signature !== 'string' || !/^sha256=[a-f0-9]{64}$/.test(signature)) throw new Error('Formato de assinatura GitHub inválido');
if (!['ping', 'push', 'pull_request', 'workflow_run'].includes(event) || typeof delivery !== 'string' || !/^[a-zA-Z0-9-]{1,100}$/.test(delivery)) throw new Error('Evento GitHub inválido');
const binary = $input.item.binary;
if (!binary?.data || Number(headers['content-length'] || 0) > 2097152) throw new Error('Corpo GitHub original ausente ou acima de 2 MiB');
// Sem parse/JSON.stringify: assinatura é validada criptograficamente pelo backend.
return {json: {signature, event, delivery}, binary: {data: {...binary.data, mimeType: 'application/json'}}};
